using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseOverMultipleTargetsCastAction", menuName = "Data/Battle/Actions/OnMouseOverMultipleTargetsCastAction")]
public class OnMouseOverMultipleTargetsCastAction : OnMouseOverNoTargetSelectionAction
{
	protected override void OnMouseOver()
	{
		base.OnMouseOver();
		for (int i = 0; i < actionTargets.Count; i++)
		{
			actionTargets[i].GetComponentInChildren<TargetInstance>().OnMouseOver();
		}
	}

	protected override void OnMouseExit()
	{
		base.OnMouseExit();
		for (int i = 0; i < actionTargets.Count; i++)
		{
			actionTargets[i].GetComponentInChildren<TargetInstance>().OnMouseExit();
		}
	}
}
